TYPES = {
    'string': str,
    'number': (int, float),
    'boolean': bool,
}


def validate(schema, args):
    props = schema['properties']
    for key in args:
        if key not in props:
            return [False, 'unknown-key:' + key]
    for key in schema['required']:
        if key not in args:
            return [False, 'missing:' + key]
    for key, spec in props.items():
        if key in args and not isinstance(args[key], TYPES[spec['type']]):
            return [False, 'type:' + key]
    return [True, '']

print(validate({'properties': {'order_id': {'type': 'string'}}, 'required': ['order_id']},
               {'order_id': 'A123'}))
